INSERT INTO public.posts (title, slug, excerpt, content, category, status, published_at, created_at) VALUES
  ('İlk Haber: Acil Tıbbın İlklerinden İsmet PARLAK vefat etti', 'ilk-haber-acil-tibbin-ilklerinden-ismet-parlak-vefat-etti', 'Yayın Hayatımıza İsmet Hocamızın Ölüm haberini derin bir üzüntü içerisinde vererek başlıyoruz. Acil Tıp camiasının saygın isimlerinden, Aksaray Eğitim ve Araştırma Hastanesi Acil Tıp Kliniği Eğitim…', '<img src="https://aciltipuzmani.com/wp-content/uploads/2025/02/GiruHlXWkAA2CZr-768x810.jpeg" height="810" width="768"/> <p>Yayın Hayatımıza İsmet Hocamızın Ölüm haberini derin bir üzüntü içerisinde vererek başlıyoruz.</p> <p>Acil Tıp camiasının saygın isimlerinden, Aksaray Eğitim ve Araştırma Hastanesi Acil Tıp Kliniği Eğitim Sorumluluğu görevini yürüten ve Aksaray Üniversitesi Acil Tıp Ana Bilim Dalı Öğretim Üyesi olan Prof. Dr. İsmet Parlak, 31 Ocak 2025 tarihinde tedavi gördüğü Ankara Bilkent Şehir Hastanesi''nde hayatını kaybetti.</p> <p>Meslek hayatı boyunca Acil Tıp alanına büyük katkılar sunan, bilgi ve deneyimiyle pek çok hekimin yetişmesine öncülük eden Prof. Dr. İsmet Parlak’ın vefatı, sağlık camiasını yasa boğdu. Değerli hocamızın kaybı, hem meslektaşları hem de öğrencileri için büyük bir kayıp olarak karşılandı.</p> <p>Merhum İsmet hocamıza Allah’tan rahmet, başta ailesi ve yakınları olmak üzere tüm sevenlerine ve Acil Tıp camiasına başsağlığı diliyoruz. Acil Tıp Uzmanları Derneği (ATUDER) ve Türkiye Acil Tıp Derneği (TATD) Yönetim Kurulları da acı kaybımız için bildiri yayınlayarak üzüntüleri paylaştılar. Prof. Dr. İsmet Parlak’a Allah’tan rahmet diliyoruz. Mekanı cennet olsun. Allah rahmet etsin.</p>', 'haber', 'published', '2025-02-05 23:47:44+03', '2025-02-05 23:47:44+03'),
  ('Kardiyojenik Şok: Patofizyoloji, Sınıflandırma ve Yönetim – II', 'kardiyojenik-sok-patofizyoloji-siniflandirma-ve-yonetim-ii', 'Yazıyı okumak için Tıklayınız', '<img src="https://aciltipuzmani.com/wp-content/uploads/2025/02/Ekran-goruntusu-2025-02-06-233654_batcheditor_fotor.jpg" height="236" width="689"/> <p><a href="https://acilci.net/kardiyojenik-sok-patofizyoloji-siniflandirma-ve-yonetim-ii/" target="_blank" rel="noopener noreferrer"><strong>Yazıyı okumak için Tıklayınız</strong></a></p>', 'acil tıp sitelerinden', 'published', '2025-02-06 22:40:04+03', '2025-02-06 22:40:04+03'),
  ('Spontana dönüş EKG’leri  - post arrest EKG ne zaman çekilmeli?', 'spontana-donus-ekgleri-post-arrest-ekg-ne-zaman-cekilmeli', 'Yazıyı okumak için Tıklayınız', '<p><img src="https://aciltipuzmani.com/wp-content/uploads/2025/02/Ekran-goruntusu-2025-02-07-185150-1.jpg" height="360" width="396"/></p><p><a href="https://xn--aciltp-t9a.com/spontana-donus-ekgleri" target="_blank" rel="noopener noreferrer"><strong>Yazıyı okumak için Tıklayınız</strong></a></p>', 'acil tıp sitelerinden', 'published', '2025-02-07 17:54:47+03', '2025-02-07 17:54:47+03'),
  ('Türkiye''deki Acil Tıp Anabilim Dalları', 'turkiyede-acil-tip-anabilim-dali-kurulmasi-ve-gelisimi', '12 Nisan 1993 tarihli kararı, 30 Nisan 1993 tarih ve 21567 sayılı Resmi Gazete ‘de 93/4270 karar sayısı ile yayınlanmış ve İlk ve Acil Yardım adıyla bir ana dal olarak kurulmuştur. Kuruluşunda 3…', '<p><b>12 Nisan 1993 tarihli kararı,</b> <b>30 Nisan 1993 tarih ve 21567 sayılı <a title="T.C. Resmî Gazete" href="https://tr.wikipedia.org/wiki/T.C._Resm%C3%AE_Gazete" target="_blank" rel="noopener noreferrer">Resmi Gazete</a>‘de 93/4270 karar sayısı</b><sup></sup> ile yayınlanmış ve <b>İlk ve Acil Yardım</b> adıyla bir ana dal olarak kurulmuştur. Kuruluşunda 3 yıllık bir ana dal olarak tanımlanan İlk ve Acil Yardım 24 ay ana dal 18 ay rotasyon şeklinde planlanmıştır. Aynı yıl Türkiye’de iki Acil Tıp Anabilim Dalı kurulmuştur (Dokuz Eylül Üniversitesi ve Fırat Üniversitesi). Bu Anabilim Dalları 1994 yılında ilk asistanlarını alarak eğitime başlamışlardır.</p> <img src="https://aciltipuzmani.com/wp-content/uploads/2025/02/Ekran-goruntusu-2025-02-10-121847.jpg" height="520" width="865"/> 9 Eylül Üniversitesin''de<strong> Oktay Eray, Cem Oktay, Yıldıray Çete, </strong> Fırat Üniversitesi''nde <strong>Murat Pekdemir</strong> (asistanlık eğitimini 9 Eylülde tamamlamıştır) ilk asistanlardandır. Aşağıdaki listede isimlerin yanındaki yıllar acil tıp AD kuruluş yıllarıdır. <ul><li><a href="https://www.deu.edu.tr/" target="_blank" rel="noopener noreferrer">Dokuz Eylül Üniversitesi</a> - İzmir - 1994 - Devlet Üniversitesi</li><li><a href="https://www.firat.edu.tr/" target="_blank" rel="noopener noreferrer">Fırat Üniversitesi</a> - Elazığ - 1994 - Devlet Üniversitesi</li><li><a href="https://www.erciyes.edu.tr/" target="_blank" rel="noopener noreferrer">Erciyes Üniversitesi</a> - Kayseri - 1995 - Devlet Üniversitesi</li><li><a href="https://www.selcuk.edu.tr/" target="_blank" rel="noopener noreferrer">Selçuk Üniversitesi</a> - Konya - 1995 - Devlet Üniversitesi</li><li><a href="https://www.nevsehir.edu.tr/" target="_blank" rel="noopener noreferrer">Necmettin Erbakan Üniversitesi</a> - Konya - 1995 - Devlet Üniversitesi</li><li><a href="https://www.dicle.edu.tr/" target="_blank" rel="noopener noreferrer">Dicle Üniversitesi</a> - Diyarbakır - 1995 - Devlet Üniversitesi</li><li><a href="https://www.marmara.edu.tr/" target="_blank" rel="noopener noreferrer">Marmara Üniversitesi</a> - İstanbul - 1995 - Devlet Üniversitesi</li><li><a href="https://www.cu.edu.tr/" target="_blank" rel="noopener noreferrer">Çukurova Üniversitesi</a> - Adana - Devlet Üniversitesi</li><li><a href="https://www.uludag.edu.tr/" target="_blank" rel="noopener noreferrer">Uludağ Üniversitesi</a> - Bursa - Devlet Üniversitesi</li><li><a href="https://www.hacettepe.edu.tr/" target="_blank" rel="noopener noreferrer">Hacettepe Üniversitesi</a> - Ankara - 1997 - Devlet Üniversitesi</li><li><a href="https://www.akdeniz.edu.tr/" target="_blank" rel="noopener noreferrer">Akdeniz Üniversitesi</a> - Antalya - Devlet Üniversitesi</li><li><a href="https://www.cumhuriyet.edu.tr/" target="_blank" rel="noopener noreferrer">Sivas Cumhuriyet Üniversitesi</a> - Sivas - Devlet Üniversitesi</li><li><a href="https://www.omu.edu.tr/" target="_blank" rel="noopener noreferrer">Ondokuz Mayıs Üniversitesi</a> - Samsun - Devlet Üniversitesi</li><li><a href="https://www.atauni.edu.tr/" target="_blank" rel="noopener noreferrer">Atatürk Üniversitesi</a> - Erzurum - Devlet Üniversitesi</li><li><a href="https://www.ktu.edu.tr/" target="_blank" rel="noopener noreferrer">Karadeniz Teknik Üniversitesi</a> - Trabzon - Devlet Üniversitesi</li><li><a href="https://www.sdu.edu.tr/" target="_blank" rel="noopener noreferrer">Süleyman Demirel Üniversitesi</a> - Isparta - Devlet Üniversitesi</li><li><a href="https://www.gulhane.edu.tr/" target="_blank" rel="noopener noreferrer">Gülhane Eğitim ve Araştırma Hastanesi</a> - Ankara - Devlet Üniversitesi</li><li><a href="https://www.inonu.edu.tr/" target="_blank" rel="no